  j constant jsonb := $j$[
{"id":"5eaccc67-1384-493d-bec4-10d3d45f0bf4","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"es","slug":"ensalada-cesar","public_path":"/ensalada-cesar","source_url":null,"title":"Ensalada César con pollo","excerpt":"Ensalada César con pollo: lechuga romana, pechuga a la plancha, crutones dorados al horno y aderezo casero de anchoa, limón y parmesano. Para 4 porciones.","summary":"La ensalada César con pollo combina hojas crujientes de lechuga romana con pechuga de pollo sellada, crutones dorados al horno y un aderezo casero de yema, anchoa, ajo, mostaza, limón, aceite de oliva y parmesano, que se emulsiona a mano con un batidor.\n\nLleva 20 minutos de preparación y 25 de cocción entre el horno y la sartén. Rinde 4 porciones.","category":"Ensaladas","difficulty":"Fácil","course":"Plato principal","cuisine":"Estadounidense","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["ensalada césar con pollo","receta de ensalada césar","aderezo césar casero","crutones caseros","ensalada césar con pechuga","cómo hacer ensalada césar","ensalada de pollo"],"ingredients":[{"name":"pan de molde","amount":"120","unit":"g","group":"Para los crutones"},{"name":"aceite de oliva","amount":"2","unit":"cucharada","group":"Para los crutones"},{"name":"sal y pimienta negra","amount":"1","unit":"pizca","group":"Para los crutones"},{"name":"pechugas de pollo","amount":"500","unit":"g","group":"Para el pollo"},{"name":"aceite de oliva","amount":"1","unit":"cucharada","group":"Para el pollo"},{"name":"sal","amount":"1/2","unit":"cucharadita","group":"Para el pollo"},{"name":"pimienta negra","amount":"1/2","unit":"cucharadita","group":"Para el pollo"},{"name":"yema de huevo","amount":"1","unit":"","group":"Para el aderezo"},{"name":"filetes de anchoa","amount":"4","unit":"","group":"Para el aderezo"},{"name":"ajo","amount":"1","unit":"","group":"Para el aderezo"},{"name":"mostaza Dijon","amount":"1","unit":"cucharadita","group":"Para el aderezo"},{"name":"jugo de limón","amount":"2","unit":"cucharada","group":"Para el aderezo"},{"name":"aceite de oliva","amount":"80","unit":"ml","group":"Para el aderezo"},{"name":"queso parmesano rallado","amount":"30","unit":"g","group":"Para el aderezo"},{"name":"lechuga romana (corazones)","amount":"2","unit":"","group":"Para la ensalada"},{"name":"queso parmesano en lascas","amount":"30","unit":"g","group":"Para la ensalada"}],"steps":[{"title":"Prepara los ingredientes","content":"Ten a mano 2 corazones de lechuga romana, 500 g de pechuga de pollo, 120 g de pan de molde, 60 g de parmesano, 1 yema de huevo, 4 filetes de anchoa, 1 diente de ajo, 1 limón, mostaza Dijon y aceite de oliva. Precalienta el horno a 180 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"Ensalada César con pollo: Prepara los ingredientes"},{"title":"Corta y sazona el pan","content":"Corta 120 g de pan de molde en cubos de 2 cm y ponlos en una bandeja con papel de horno. Mézclalos con 2 cucharadas de aceite de oliva y una pizca de sal y pimienta, y extiéndelos en una sola capa.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"Ensalada César con pollo: Corta y sazona el pan"},{"title":"Hornea los crutones","content":"Hornéalos a 180 °C de 12 a 15 minutos, removiéndolos a la mitad, hasta que estén dorados y crujientes. Déjalos enfriar en la bandeja.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"Ensalada César con pollo: Hornea los crutones"},{"title":"Sella el pollo","content":"Aplana 2 pechugas hasta unos 2 cm de grosor y sazónalas con ½ cucharadita de sal y ½ cucharadita de pimienta. Calienta 1 cucharada de aceite en una sartén a fuego medio-alto y cocínalas de 5 a 6 minutos por lado, hasta que el centro alcance 74 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"Ensalada César con pollo: Sella el pollo"},{"title":"Reposa y corta el pollo","content":"Pasa el pollo a una tabla, déjalo reposar 5 minutos para que no suelte los jugos y córtalo en lonchas de 1 cm, en diagonal.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"Ensalada César con pollo: Reposa y corta el pollo"},{"title":"Bate el aderezo","content":"En un bol bate 1 yema, 4 filetes de anchoa picados muy finos, 1 ajo rallado, 1 cucharadita de mostaza y 2 cucharadas de jugo de limón. Añade 80 ml de aceite de oliva en hilo fino, sin dejar de batir, hasta que espese. Incorpora 30 g de parmesano rallado y pimienta al gusto.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"Ensalada César con pollo: Bate el aderezo"},{"title":"Mezcla la lechuga","content":"Lava y seca muy bien los 2 corazones de romana, trocéalos en pedazos de 4 a 5 cm y mézclalos con tres cuartas partes del aderezo hasta cubrir todas las hojas.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"Ensalada César con pollo: Mezcla la lechuga"},{"title":"Monta y sirve","content":"Reparte la lechuga en 4 platos, coloca encima el pollo y los crutones, añade 30 g de parmesano en lascas y el aderezo que quedó. Sírvela enseguida, con limón al lado.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"Ensalada César con pollo: Monta y sirve"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"Ensalada César con pollo"}],"notes":"Seca bien la lechuga: si queda húmeda, el aderezo resbala y la ensalada queda aguada. Aliña justo antes de servir para que las hojas y los crutones sigan crujientes. El aderezo lleva yema cruda; si lo vas a servir a niños, embarazadas o personas mayores, usa huevo pasteurizado. Contiene huevo, pescado (anchoa), lácteos y gluten. El aderezo se conserva hasta 2 días en la nevera, en un frasco cerrado; los crutones, 3 días en un recipiente hermético a temperatura ambiente. El pollo se puede preparar antes y servir templado o frío.","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1 porción (un plato, unos 280 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones: 400 g de lechuga romana, 500 g de pechuga de pollo cruda, 120 g de pan de molde, 60 g de parmesano, 17 g de yema, 12 g de anchoa, 4 g de ajo, 5 g de mostaza (valores aproximados), 30 g de jugo de limón, 3,5 g de sal, 2 g de pimienta y 113,5 g de aceite de oliva, que es todo el aceite de la receta, aunque parte quede en la sartén o en el bol.","note":"Estimación por porción. El aceite que realmente se consume y el tamaño del pan varían.","inputs":[{"fdc_id":"169247","description":"Lettuce, cos or romaine, raw (2 corazones ≈ 400 g)","grams":400,"per100":{"calories":17,"protein_g":1.23,"carbs_g":3.29,"fat_g":0.3,"saturated_fat_g":0.039,"fiber_g":2.1,"sodium_mg":8}},{"fdc_id":"171077","description":"Chicken, broilers or fryers, breast, meat only, raw (500 g)","grams":500,"per100":{"calories":120,"protein_g":22.5,"carbs_g":0,"fat_g":2.62,"saturated_fat_g":0.563,"fiber_g":0,"sodium_mg":45}},{"fdc_id":"172686","description":"Bread, white, commercially prepared (120 g de pan de molde)","grams":120,"per100":{"calories":266,"protein_g":8.85,"carbs_g":50.61,"fat_g":3.33,"saturated_fat_g":0.7,"fiber_g":2.3,"sodium_mg":491}},{"fdc_id":"171247","description":"Cheese, parmesan, hard (60 g: 30 g en el aderezo y 30 g en lascas)","grams":60,"per100":{"calories":392,"protein_g":35.75,"carbs_g":3.22,"fat_g":25.83,"saturated_fat_g":16.41,"fiber_g":0,"sodium_mg":1529}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (27 g de los crutones + 13,5 g del pollo + 73 g del aderezo; se cuenta todo)","grams":113.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"172184","description":"Egg, yolk, raw, fresh (1 yema ≈ 17 g)","grams":17,"per100":{"calories":322,"protein_g":15.86,"carbs_g":3.59,"fat_g":26.54,"saturated_fat_g":9.551,"fiber_g":0,"sodium_mg":48}},{"fdc_id":"175139","description":"Fish, anchovy, european, canned in oil, drained solids (4 filetes ≈ 12 g)","grams":12,"per100":{"calories":210,"protein_g":28.89,"carbs_g":0,"fat_g":9.71,"saturated_fat_g":2.2,"fiber_g":0,"sodium_mg":3668}},{"fdc_id":"169230","description":"Garlic, raw (1 diente ≈ 4 g)","grams":4,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":null,"description":"Mustard, prepared (proxy de la mostaza Dijon, 1 cucharadita ≈ 5 g; valores aproximados)","grams":5,"per100":{"calories":66,"protein_g":4.4,"carbs_g":5.8,"fat_g":4,"saturated_fat_g":0.2,"fiber_g":3.3,"sodium_mg":1135}},{"fdc_id":"167747","description":"Lemon juice, raw (2 cucharadas ≈ 30 g)","grams":30,"per100":{"calories":22,"protein_g":0.35,"carbs_g":6.9,"fat_g":0.24,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1}},{"fdc_id":"173468","description":"Salt, table (3,5 g: ½ cucharadita del pollo y una pizca de los crutones)","grams":3.5,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"170931","description":"Spices, pepper, black (2 g)","grams":2,"per100":{"calories":251,"protein_g":10.39,"carbs_g":63.95,"fat_g":3.26,"saturated_fat_g":1.392,"fiber_g":25.3,"sodium_mg":20}}]},"seo":{"title":"Ensalada César con pollo: aderezo casero y crutones | Manual de Cocina","description":"Ensalada César con pollo: lechuga romana, pechuga sellada, crutones al horno y aderezo casero de anchoa, limón y parmesano. 4 porciones. Paso a paso con fotos.","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"¿Lleva anchoa el aderezo César?","a":"Sí, la anchoa es la base del sabor del aderezo clásico. Picada muy fina se deshace en la emulsión y no deja gusto a pescado fuerte. Sin anchoa el aderezo cambia bastante."},{"q":"¿Cómo hago que el aderezo no se corte?","a":"Añade el aceite en hilo muy fino mientras bates sin parar, y empieza con todos los ingredientes a temperatura ambiente. Si se corta, bate otra yema aparte y agrégale el aderezo poco a poco."},{"q":"¿Puedo preparar los crutones con antelación?","a":"Sí. Se conservan 3 días en un recipiente hermético a temperatura ambiente. Si se ablandan, devuélvelos 5 minutos al horno."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"e89b9c6e-3691-538a-b122-b2243149de47","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"de","slug":"caesar-salat-mit-haehnchen","public_path":"/de/caesar-salat-mit-haehnchen","source_url":null,"title":"Caesar Salad mit Hähnchen","excerpt":"Caesar Salad mit Hähnchen: Romanasalat, gebratene Hähnchenbrust, goldene Croûtons aus dem Ofen und hausgemachtes Dressing mit Sardelle, Zitrone und Parmesan. 4 Portionen.","summary":"Der Caesar Salad mit Hähnchen verbindet knackigen Romanasalat mit scharf angebratener Hähnchenbrust, goldenen Croûtons aus dem Ofen und einem hausgemachten Dressing aus Eigelb, Sardelle, Knoblauch, Senf, Zitrone, Olivenöl und Parmesan, das von Hand mit dem Schneebesen emulgiert wird.\n\nEr braucht 20 Minuten Vorbereitung und 25 Minuten Garzeit in Ofen und Pfanne. Ergibt 4 Portionen.","category":"Salate","difficulty":"Einfach","course":"Hauptgericht","cuisine":"Amerikanisch","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["Caesar Salad mit Hähnchen","Caesar Salad Rezept","Caesar Dressing selber machen","Croûtons selber machen","Caesar Salad mit Hähnchenbrust","Hähnchensalat","Salat mit Hähnchen"],"ingredients":[{"name":"Toastbrot","amount":"120","unit":"g","group":"Für die Croûtons"},{"name":"Olivenöl","amount":"2","unit":"Esslöffel","group":"Für die Croûtons"},{"name":"Salz und schwarzer Pfeffer","amount":"1","unit":"Prise","group":"Für die Croûtons"},{"name":"Hähnchenbrustfilets","amount":"500","unit":"g","group":"Für das Hähnchen"},{"name":"Olivenöl","amount":"1","unit":"Esslöffel","group":"Für das Hähnchen"},{"name":"Salz","amount":"1/2","unit":"Teelöffel","group":"Für das Hähnchen"},{"name":"schwarzer Pfeffer","amount":"1/2","unit":"Teelöffel","group":"Für das Hähnchen"},{"name":"Eigelb","amount":"1","unit":"","group":"Für das Dressing"},{"name":"Sardellenfilets","amount":"4","unit":"","group":"Für das Dressing"},{"name":"Knoblauch","amount":"1","unit":"","group":"Für das Dressing"},{"name":"Dijon-Senf","amount":"1","unit":"Teelöffel","group":"Für das Dressing"},{"name":"Zitronensaft","amount":"2","unit":"Esslöffel","group":"Für das Dressing"},{"name":"Olivenöl","amount":"80","unit":"ml","group":"Für das Dressing"},{"name":"geriebener Parmesan","amount":"30","unit":"g","group":"Für das Dressing"},{"name":"Romanasalatherzen","amount":"2","unit":"","group":"Für den Salat"},{"name":"Parmesan in Spänen","amount":"30","unit":"g","group":"Für den Salat"}],"steps":[{"title":"Zutaten vorbereiten","content":"2 Romanasalatherzen, 500 g Hähnchenbrust, 120 g Toastbrot, 60 g Parmesan, 1 Eigelb, 4 Sardellenfilets, 1 Knoblauchzehe, 1 Zitrone, Dijon-Senf und Olivenöl bereitstellen. Den Backofen auf 180 °C vorheizen.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"Caesar Salad mit Hähnchen: Zutaten vorbereiten"},{"title":"Brot schneiden und würzen","content":"120 g Toastbrot in 2-cm-Würfel schneiden und auf ein mit Backpapier belegtes Blech geben. Mit 2 Esslöffeln Olivenöl und einer Prise Salz und Pfeffer mischen und in einer Schicht verteilen.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"Caesar Salad mit Hähnchen: Brot schneiden und würzen"},{"title":"Croûtons backen","content":"Bei 180 °C 12 bis 15 Minuten backen, dabei einmal wenden, bis sie goldbraun und knusprig sind. Auf dem Blech abkühlen lassen.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"Caesar Salad mit Hähnchen: Croûtons backen"},{"title":"Hähnchen anbraten","content":"2 Hähnchenbrüste auf etwa 2 cm Dicke flach klopfen und mit ½ Teelöffel Salz und ½ Teelöffel Pfeffer würzen. 1 Esslöffel Öl in einer Pfanne bei mittlerer bis hoher Hitze erhitzen und die Brüste 5 bis 6 Minuten pro Seite braten, bis die Kerntemperatur 74 °C erreicht.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"Caesar Salad mit Hähnchen: Hähnchen anbraten"},{"title":"Hähnchen ruhen lassen und schneiden","content":"Das Hähnchen auf ein Brett legen, 5 Minuten ruhen lassen, damit der Saft nicht ausläuft, und schräg in 1 cm dicke Scheiben schneiden.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"Caesar Salad mit Hähnchen: Hähnchen ruhen lassen und schneiden"},{"title":"Dressing aufschlagen","content":"1 Eigelb, 4 sehr fein gehackte Sardellenfilets, 1 geriebene Knoblauchzehe, 1 Teelöffel Senf und 2 Esslöffel Zitronensaft in einer Schüssel verrühren. 80 ml Olivenöl in dünnem Strahl unter ständigem Rühren einlaufen lassen, bis das Dressing bindet. 30 g geriebenen Parmesan und nach Geschmack Pfeffer unterrühren.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"Caesar Salad mit Hähnchen: Dressing aufschlagen"},{"title":"Salat anmachen","content":"Die 2 Romanasalatherzen waschen und gut trocken schleudern, in 4 bis 5 cm große Stücke zupfen und mit drei Vierteln des Dressings mischen, bis alle Blätter überzogen sind.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"Caesar Salad mit Hähnchen: Salat anmachen"},{"title":"Anrichten und servieren","content":"Den Salat auf 4 Teller verteilen, Hähnchen und Croûtons darauflegen, 30 g Parmesan in Spänen darüberstreuen und das restliche Dressing dazugeben. Sofort mit Zitrone servieren.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"Caesar Salad mit Hähnchen: Anrichten und servieren"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"Caesar Salad mit Hähnchen"}],"notes":"Den Salat gut trocknen: Ist er nass, rutscht das Dressing ab und der Salat wird wässrig. Erst kurz vor dem Servieren anmachen, damit Blätter und Croûtons knusprig bleiben. Das Dressing enthält rohes Eigelb; für Kinder, Schwangere und ältere Menschen pasteurisiertes Ei verwenden. Enthält Ei, Fisch (Sardelle), Milch und Gluten. Das Dressing hält sich 2 Tage im Kühlschrank in einem verschlossenen Glas, die Croûtons 3 Tage in einer dichten Dose bei Raumtemperatur. Das Hähnchen lässt sich vorbereiten und lauwarm oder kalt servieren.","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1 Portion (ein Teller, etwa 280 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt: 400 g Romanasalat, 500 g rohe Hähnchenbrust, 120 g Toastbrot, 60 g Parmesan, 17 g Eigelb, 12 g Sardelle, 4 g Knoblauch, 5 g Senf (ungefähre Werte), 30 g Zitronensaft, 3,5 g Salz, 2 g Pfeffer und 113,5 g Olivenöl, also das gesamte Öl des Rezepts, auch wenn ein Teil in Pfanne oder Schüssel bleibt.","note":"Schätzung pro Portion. Das tatsächlich verzehrte Öl und die Brotgröße schwanken."},"seo":{"title":"Caesar Salad mit Hähnchen: Dressing und Croûtons selbst gemacht | Manual de Cocina","description":"Caesar Salad mit Hähnchen: Romanasalat, gebratene Hähnchenbrust, Croûtons aus dem Ofen und Dressing mit Sardelle, Zitrone, Parmesan. 4 Portionen. Mit Fotos.","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"Gehört Sardelle ins Caesar Dressing?","a":"Ja, die Sardelle ist die geschmackliche Basis des klassischen Dressings. Sehr fein gehackt löst sie sich in der Emulsion auf und schmeckt nicht stark nach Fisch. Ohne Sardelle verändert sich das Dressing deutlich."},{"q":"Wie verhindere ich, dass das Dressing gerinnt?","a":"Das Öl in sehr dünnem Strahl einlaufen lassen und dabei ständig rühren; alle Zutaten sollten Raumtemperatur haben. Ist es geronnen, ein weiteres Eigelb separat verrühren und das Dressing nach und nach unterschlagen."},{"q":"Kann ich die Croûtons vorbereiten?","a":"Ja. Sie halten sich 3 Tage in einer dichten Dose bei Raumtemperatur. Werden sie weich, 5 Minuten zurück in den Ofen geben."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"c122a060-f8bf-507c-a272-d65fe291a757","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"en","slug":"chicken-caesar-salad","public_path":"/en/chicken-caesar-salad","source_url":null,"title":"Chicken Caesar Salad","excerpt":"Chicken Caesar salad: romaine lettuce, seared chicken breast, golden oven-baked croutons and a homemade anchovy, lemon and Parmesan dressing. Serves 4.","summary":"Chicken Caesar salad pairs crisp romaine lettuce with seared chicken breast, golden oven-baked croutons and a homemade dressing of egg yolk, anchovy, garlic, mustard, lemon, olive oil and Parmesan, emulsified by hand with a whisk.\n\nIt takes 20 minutes of prep and 25 of cooking between the oven and the skillet. It serves 4.","category":"Salads","difficulty":"Easy","course":"Main course","cuisine":"American","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["chicken Caesar salad","Caesar salad recipe","homemade Caesar dressing","homemade croutons","Caesar salad with chicken breast","how to make Caesar salad","chicken salad"],"ingredients":[{"name":"sandwich bread","amount":"120","unit":"g","group":"For the croutons"},{"name":"olive oil","amount":"2","unit":"tablespoon","group":"For the croutons"},{"name":"salt and black pepper","amount":"1","unit":"pinch","group":"For the croutons"},{"name":"chicken breasts","amount":"500","unit":"g","group":"For the chicken"},{"name":"olive oil","amount":"1","unit":"tablespoon","group":"For the chicken"},{"name":"salt","amount":"1/2","unit":"teaspoon","group":"For the chicken"},{"name":"black pepper","amount":"1/2","unit":"teaspoon","group":"For the chicken"},{"name":"egg yolk","amount":"1","unit":"","group":"For the dressing"},{"name":"anchovy fillets","amount":"4","unit":"","group":"For the dressing"},{"name":"garlic","amount":"1","unit":"","group":"For the dressing"},{"name":"Dijon mustard","amount":"1","unit":"teaspoon","group":"For the dressing"},{"name":"lemon juice","amount":"2","unit":"tablespoon","group":"For the dressing"},{"name":"olive oil","amount":"80","unit":"ml","group":"For the dressing"},{"name":"grated Parmesan","amount":"30","unit":"g","group":"For the dressing"},{"name":"romaine hearts","amount":"2","unit":"","group":"For the salad"},{"name":"shaved Parmesan","amount":"30","unit":"g","group":"For the salad"}],"steps":[{"title":"Prepare the ingredients","content":"Have ready 2 romaine hearts, 500 g chicken breast, 120 g sandwich bread, 60 g Parmesan, 1 egg yolk, 4 anchovy fillets, 1 garlic clove, 1 lemon, Dijon mustard and olive oil. Preheat the oven to 180 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"Chicken Caesar Salad: Prepare the ingredients"},{"title":"Cut and season the bread","content":"Cut 120 g sandwich bread into 2 cm cubes and put them on a baking sheet lined with parchment. Toss with 2 tablespoons olive oil and a pinch of salt and pepper, and spread in a single layer.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"Chicken Caesar Salad: Cut and season the bread"},{"title":"Bake the croutons","content":"Bake at 180 °C for 12 to 15 minutes, stirring halfway, until golden and crisp. Let them cool on the sheet.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"Chicken Caesar Salad: Bake the croutons"},{"title":"Sear the chicken","content":"Flatten 2 chicken breasts to about 2 cm thick and season with ½ teaspoon salt and ½ teaspoon pepper. Heat 1 tablespoon oil in a skillet over medium-high heat and cook the breasts 5 to 6 minutes per side, until the center reaches 74 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"Chicken Caesar Salad: Sear the chicken"},{"title":"Rest and slice the chicken","content":"Move the chicken to a board, let it rest for 5 minutes so it keeps its juices, and slice it on the diagonal into 1 cm slices.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"Chicken Caesar Salad: Rest and slice the chicken"},{"title":"Whisk the dressing","content":"In a bowl, whisk 1 egg yolk, 4 very finely chopped anchovy fillets, 1 grated garlic clove, 1 teaspoon mustard and 2 tablespoons lemon juice. Drizzle in 80 ml olive oil in a thin stream, whisking constantly, until thickened. Stir in 30 g grated Parmesan and pepper to taste.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"Chicken Caesar Salad: Whisk the dressing"},{"title":"Toss the lettuce","content":"Wash and thoroughly dry the 2 romaine hearts, tear them into 4 to 5 cm pieces and toss with three quarters of the dressing until every leaf is coated.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"Chicken Caesar Salad: Toss the lettuce"},{"title":"Assemble and serve","content":"Divide the lettuce among 4 plates, top with the chicken and croutons, add 30 g shaved Parmesan and the remaining dressing. Serve right away, with lemon on the side.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"Chicken Caesar Salad: Assemble and serve"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"Chicken Caesar Salad"}],"notes":"Dry the lettuce well: if it is wet, the dressing slides off and the salad turns watery. Dress it right before serving so the leaves and croutons stay crisp. The dressing contains raw egg yolk; for children, pregnant women or older people, use pasteurized egg. Contains egg, fish (anchovy), dairy and gluten. The dressing keeps for 2 days in the fridge in a closed jar; the croutons keep for 3 days in an airtight container at room temperature. The chicken can be made ahead and served warm or cold.","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1 serving (one plate, about 280 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings: 400 g romaine lettuce, 500 g raw chicken breast, 120 g sandwich bread, 60 g Parmesan, 17 g egg yolk, 12 g anchovy, 4 g garlic, 5 g mustard (approximate values), 30 g lemon juice, 3.5 g salt, 2 g pepper and 113.5 g olive oil, which is all the oil in the recipe even though some stays in the skillet or the bowl.","note":"Estimate per serving. The oil actually eaten and the size of the bread vary."},"seo":{"title":"Chicken Caesar Salad with Homemade Dressing and Croutons | Manual de Cocina","description":"Chicken Caesar salad: romaine, seared chicken breast, oven-baked croutons and a homemade anchovy, lemon and Parmesan dressing. Serves 4. Step by step with photos.","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"Does Caesar dressing have anchovy?","a":"Yes, anchovy is the flavor base of the classic dressing. Very finely chopped, it dissolves into the emulsion and does not taste strongly of fish. Without anchovy the dressing changes a lot."},{"q":"How do I keep the dressing from splitting?","a":"Add the oil in a very thin stream while whisking constantly, and start with all the ingredients at room temperature. If it splits, whisk another yolk in a clean bowl and add the split dressing a little at a time."},{"q":"Can I make the croutons ahead?","a":"Yes. They keep for 3 days in an airtight container at room temperature. If they soften, put them back in the oven for 5 minutes."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"6958cc9b-b05f-5ddf-b41b-4702cea782bc","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"fr","slug":"salade-cesar-au-poulet","public_path":"/fr/salade-cesar-au-poulet","source_url":null,"title":"Salade César au poulet","excerpt":"Salade César au poulet : romaine, blanc de poulet saisi, croûtons dorés au four et sauce maison à l'anchois, au citron et au parmesan. Pour 4 portions.","summary":"La salade César au poulet associe la romaine croquante à un blanc de poulet saisi, des croûtons dorés au four et une sauce maison au jaune d'œuf, à l'anchois, à l'ail, à la moutarde, au citron, à l'huile d'olive et au parmesan, émulsionnée à la main au fouet.\n\nElle demande 20 minutes de préparation et 25 de cuisson entre le four et la poêle. Pour 4 portions.","category":"Salades","difficulty":"Facile","course":"Plat principal","cuisine":"Américaine","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["salade césar au poulet","recette salade césar","sauce césar maison","croûtons maison","salade césar au blanc de poulet","comment faire une salade césar","salade de poulet"],"ingredients":[{"name":"pain de mie","amount":"120","unit":"g","group":"Pour les croûtons"},{"name":"huile d'olive","amount":"2","unit":"cuillère à soupe","group":"Pour les croûtons"},{"name":"sel et poivre noir","amount":"1","unit":"pincée","group":"Pour les croûtons"},{"name":"blancs de poulet","amount":"500","unit":"g","group":"Pour le poulet"},{"name":"huile d'olive","amount":"1","unit":"cuillère à soupe","group":"Pour le poulet"},{"name":"sel","amount":"1/2","unit":"cuillère à café","group":"Pour le poulet"},{"name":"poivre noir","amount":"1/2","unit":"cuillère à café","group":"Pour le poulet"},{"name":"jaune d'œuf","amount":"1","unit":"","group":"Pour la sauce"},{"name":"filets d'anchois","amount":"4","unit":"","group":"Pour la sauce"},{"name":"ail","amount":"1","unit":"","group":"Pour la sauce"},{"name":"moutarde de Dijon","amount":"1","unit":"cuillère à café","group":"Pour la sauce"},{"name":"jus de citron","amount":"2","unit":"cuillère à soupe","group":"Pour la sauce"},{"name":"huile d'olive","amount":"80","unit":"ml","group":"Pour la sauce"},{"name":"parmesan râpé","amount":"30","unit":"g","group":"Pour la sauce"},{"name":"cœurs de romaine","amount":"2","unit":"","group":"Pour la salade"},{"name":"parmesan en copeaux","amount":"30","unit":"g","group":"Pour la salade"}],"steps":[{"title":"Préparer les ingrédients","content":"Prévoir 2 cœurs de romaine, 500 g de blanc de poulet, 120 g de pain de mie, 60 g de parmesan, 1 jaune d'œuf, 4 filets d'anchois, 1 gousse d'ail, 1 citron, de la moutarde de Dijon et de l'huile d'olive. Préchauffer le four à 180 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"Salade César au poulet: Préparer les ingrédients"},{"title":"Couper et assaisonner le pain","content":"Couper 120 g de pain de mie en dés de 2 cm et les poser sur une plaque recouverte de papier sulfurisé. Les mélanger avec 2 cuillères à soupe d'huile d'olive et une pincée de sel et de poivre, puis les étaler en une seule couche.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"Salade César au poulet: Couper et assaisonner le pain"},{"title":"Cuire les croûtons","content":"Cuire à 180 °C de 12 à 15 minutes, en les remuant à mi-cuisson, jusqu'à ce qu'ils soient dorés et croustillants. Les laisser refroidir sur la plaque.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"Salade César au poulet: Cuire les croûtons"},{"title":"Saisir le poulet","content":"Aplatir 2 blancs de poulet à environ 2 cm d'épaisseur et les assaisonner avec ½ cuillère à café de sel et ½ cuillère à café de poivre. Chauffer 1 cuillère à soupe d'huile dans une poêle à feu moyen-vif et cuire les blancs 5 à 6 minutes de chaque côté, jusqu'à ce que le centre atteigne 74 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"Salade César au poulet: Saisir le poulet"},{"title":"Laisser reposer et trancher le poulet","content":"Poser le poulet sur une planche, le laisser reposer 5 minutes pour qu'il garde son jus et le couper en biais en tranches de 1 cm.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"Salade César au poulet: Laisser reposer et trancher le poulet"},{"title":"Fouetter la sauce","content":"Dans un bol, fouetter 1 jaune d'œuf, 4 filets d'anchois hachés très finement, 1 gousse d'ail râpée, 1 cuillère à café de moutarde et 2 cuillères à soupe de jus de citron. Verser 80 ml d'huile d'olive en filet fin, sans cesser de fouetter, jusqu'à épaississement. Incorporer 30 g de parmesan râpé et du poivre selon le goût.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"Salade César au poulet: Fouetter la sauce"},{"title":"Mélanger la salade","content":"Laver et bien essorer les 2 cœurs de romaine, les couper en morceaux de 4 à 5 cm et les mélanger avec les trois quarts de la sauce jusqu'à enrober toutes les feuilles.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"Salade César au poulet: Mélanger la salade"},{"title":"Dresser et servir","content":"Répartir la salade dans 4 assiettes, ajouter le poulet et les croûtons, 30 g de parmesan en copeaux et le reste de la sauce. Servir aussitôt, avec du citron à côté.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"Salade César au poulet: Dresser et servir"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"Salade César au poulet"}],"notes":"Bien essorer la salade : si elle est humide, la sauce glisse et la salade devient aqueuse. L'assaisonner juste avant de servir pour que les feuilles et les croûtons restent croquants. La sauce contient du jaune d'œuf cru ; pour les enfants, les femmes enceintes ou les personnes âgées, utiliser un œuf pasteurisé. Contient œuf, poisson (anchois), lait et gluten. La sauce se garde 2 jours au réfrigérateur dans un bocal fermé, les croûtons 3 jours dans une boîte hermétique à température ambiante. Le poulet peut être préparé à l'avance et servi tiède ou froid.","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1 portion (une assiette, environ 280 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions : 400 g de romaine, 500 g de blanc de poulet cru, 120 g de pain de mie, 60 g de parmesan, 17 g de jaune d'œuf, 12 g d'anchois, 4 g d'ail, 5 g de moutarde (valeurs approximatives), 30 g de jus de citron, 3,5 g de sel, 2 g de poivre et 113,5 g d'huile d'olive, soit toute l'huile de la recette, même si une partie reste dans la poêle ou le bol.","note":"Estimation par portion. L'huile réellement consommée et la taille du pain varient."},"seo":{"title":"Salade César au poulet : sauce et croûtons maison | Manual de Cocina","description":"Salade César au poulet : romaine, blanc de poulet saisi, croûtons au four et sauce maison à l'anchois, au citron et au parmesan. 4 portions. Pas à pas en photos.","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"La sauce César contient-elle de l'anchois ?","a":"Oui, l'anchois est la base du goût de la sauce classique. Haché très finement, il se fond dans l'émulsion et ne donne pas un goût de poisson marqué. Sans anchois, la sauce change beaucoup."},{"q":"Comment éviter que la sauce tranche ?","a":"Verser l'huile en filet très fin en fouettant sans arrêt, et partir d'ingrédients à température ambiante. Si elle tranche, fouetter un autre jaune dans un bol propre et y incorporer la sauce peu à peu."},{"q":"Peut-on préparer les croûtons à l'avance ?","a":"Oui. Ils se gardent 3 jours dans une boîte hermétique à température ambiante. S'ils ramollissent, les remettre 5 minutes au four."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"a61340ba-128d-5d37-a6f0-6921307a2abc","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"it","slug":"insalata-caesar-con-pollo","public_path":"/it/insalata-caesar-con-pollo","source_url":null,"title":"Insalata Caesar con pollo","excerpt":"Insalata Caesar con pollo: lattuga romana, petto di pollo scottato, crostini dorati al forno e salsa fatta in casa con acciuga, limone e parmigiano. Per 4 porzioni.","summary":"L'insalata Caesar con pollo unisce la lattuga romana croccante a petto di pollo scottato, crostini dorati al forno e una salsa fatta in casa con tuorlo, acciuga, aglio, senape, limone, olio d'oliva e parmigiano, emulsionata a mano con la frusta.\n\nRichiede 20 minuti di preparazione e 25 di cottura tra forno e padella. Per 4 porzioni.","category":"Insalate","difficulty":"Facile","course":"Piatto principale","cuisine":"Americana","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["insalata caesar con pollo","ricetta insalata caesar","salsa caesar fatta in casa","crostini fatti in casa","insalata caesar con petto di pollo","come fare l'insalata caesar","insalata di pollo"],"ingredients":[{"name":"pane in cassetta","amount":"120","unit":"g","group":"Per i crostini"},{"name":"olio d'oliva","amount":"2","unit":"cucchiaio","group":"Per i crostini"},{"name":"sale e pepe nero","amount":"1","unit":"pizzico","group":"Per i crostini"},{"name":"petti di pollo","amount":"500","unit":"g","group":"Per il pollo"},{"name":"olio d'oliva","amount":"1","unit":"cucchiaio","group":"Per il pollo"},{"name":"sale","amount":"1/2","unit":"cucchiaino","group":"Per il pollo"},{"name":"pepe nero","amount":"1/2","unit":"cucchiaino","group":"Per il pollo"},{"name":"tuorlo d'uovo","amount":"1","unit":"","group":"Per la salsa"},{"name":"filetti di acciuga","amount":"4","unit":"","group":"Per la salsa"},{"name":"aglio","amount":"1","unit":"","group":"Per la salsa"},{"name":"senape di Digione","amount":"1","unit":"cucchiaino","group":"Per la salsa"},{"name":"succo di limone","amount":"2","unit":"cucchiaio","group":"Per la salsa"},{"name":"olio d'oliva","amount":"80","unit":"ml","group":"Per la salsa"},{"name":"parmigiano grattugiato","amount":"30","unit":"g","group":"Per la salsa"},{"name":"cuori di lattuga romana","amount":"2","unit":"","group":"Per l'insalata"},{"name":"parmigiano a scaglie","amount":"30","unit":"g","group":"Per l'insalata"}],"steps":[{"title":"Prepara gli ingredienti","content":"Tieni pronti 2 cuori di lattuga romana, 500 g di petto di pollo, 120 g di pane in cassetta, 60 g di parmigiano, 1 tuorlo, 4 filetti di acciuga, 1 spicchio d'aglio, 1 limone, senape di Digione e olio d'oliva. Preriscalda il forno a 180 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"Insalata Caesar con pollo: Prepara gli ingredienti"},{"title":"Taglia e condisci il pane","content":"Taglia 120 g di pane in cassetta a cubetti di 2 cm e mettili su una teglia con carta da forno. Mescolali con 2 cucchiai di olio d'oliva e un pizzico di sale e pepe e distribuiscili in un solo strato.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"Insalata Caesar con pollo: Taglia e condisci il pane"},{"title":"Inforna i crostini","content":"Cuoci a 180 °C per 12-15 minuti, mescolando a metà cottura, finché sono dorati e croccanti. Lasciali raffreddare sulla teglia.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"Insalata Caesar con pollo: Inforna i crostini"},{"title":"Scotta il pollo","content":"Appiattisci 2 petti di pollo fino a circa 2 cm di spessore e condiscili con ½ cucchiaino di sale e ½ cucchiaino di pepe. Scalda 1 cucchiaio di olio in una padella a fuoco medio-alto e cuoci i petti 5-6 minuti per lato, finché il centro raggiunge 74 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"Insalata Caesar con pollo: Scotta il pollo"},{"title":"Lascia riposare e affetta il pollo","content":"Trasferisci il pollo su un tagliere, lascialo riposare 5 minuti perché trattenga i succhi e affettalo in diagonale a fette di 1 cm.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"Insalata Caesar con pollo: Lascia riposare e affetta il pollo"},{"title":"Monta la salsa","content":"In una ciotola sbatti 1 tuorlo, 4 filetti di acciuga tritati finissimi, 1 spicchio d'aglio grattugiato, 1 cucchiaino di senape e 2 cucchiai di succo di limone. Versa 80 ml di olio d'oliva a filo sottile, sempre sbattendo, finché si addensa. Unisci 30 g di parmigiano grattugiato e pepe a piacere.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"Insalata Caesar con pollo: Monta la salsa"},{"title":"Condisci la lattuga","content":"Lava e asciuga molto bene i 2 cuori di romana, spezzali in pezzi di 4-5 cm e mescolali con tre quarti della salsa finché tutte le foglie sono ricoperte.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"Insalata Caesar con pollo: Condisci la lattuga"},{"title":"Componi e servi","content":"Distribuisci la lattuga in 4 piatti, aggiungi il pollo e i crostini, 30 g di parmigiano a scaglie e la salsa rimasta. Servi subito, con limone a parte.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"Insalata Caesar con pollo: Componi e servi"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"Insalata Caesar con pollo"}],"notes":"Asciuga bene la lattuga: se è bagnata, la salsa scivola via e l'insalata diventa acquosa. Condiscila subito prima di servire perché foglie e crostini restino croccanti. La salsa contiene tuorlo crudo; per bambini, donne in gravidanza o anziani usa uovo pastorizzato. Contiene uovo, pesce (acciuga), latte e glutine. La salsa si conserva 2 giorni in frigorifero in un vasetto chiuso, i crostini 3 giorni in un contenitore ermetico a temperatura ambiente. Il pollo si può preparare in anticipo e servire tiepido o freddo.","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1 porzione (un piatto, circa 280 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni: 400 g di lattuga romana, 500 g di petto di pollo crudo, 120 g di pane in cassetta, 60 g di parmigiano, 17 g di tuorlo, 12 g di acciuga, 4 g di aglio, 5 g di senape (valori approssimativi), 30 g di succo di limone, 3,5 g di sale, 2 g di pepe e 113,5 g di olio d'oliva, cioè tutto l'olio della ricetta, anche se una parte resta nella padella o nella ciotola.","note":"Stima per porzione. L'olio effettivamente consumato e la dimensione del pane variano."},"seo":{"title":"Insalata Caesar con pollo: salsa e crostini fatti in casa | Manual de Cocina","description":"Insalata Caesar con pollo: lattuga romana, petto di pollo scottato, crostini al forno e salsa con acciuga, limone e parmigiano. 4 porzioni. Passo dopo passo con foto.","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"La salsa Caesar contiene acciuga?","a":"Sì, l'acciuga è la base del sapore della salsa classica. Tritata finissima si scioglie nell'emulsione e non dà un forte gusto di pesce. Senza acciuga la salsa cambia molto."},{"q":"Come evito che la salsa impazzisca?","a":"Versa l'olio a filo sottilissimo sbattendo di continuo e parti da ingredienti a temperatura ambiente. Se impazzisce, sbatti un altro tuorlo in una ciotola pulita e aggiungi la salsa impazzita a poco a poco."},{"q":"Posso preparare i crostini in anticipo?","a":"Sì. Si conservano 3 giorni in un contenitore ermetico a temperatura ambiente. Se si ammorbidiscono, rimettili in forno per 5 minuti."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"d557cb7c-2701-5c3f-aeda-30abf8090aea","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"ja","slug":"チキンシーザーサラダ","public_path":"/ja/チキンシーザーサラダ","source_url":null,"title":"チキンシーザーサラダ","excerpt":"ロメインレタス、焼いた鶏むね肉、オーブンで焼いたカリカリのクルトン、アンチョビとレモンとパルメザンの手作りドレッシングで作るシーザーサラダ。4人分です。","summary":"チキンシーザーサラダは、シャキシャキのロメインレタスに、焼いた鶏むね肉、オーブンで黄金色に焼いたクルトン、卵黄・アンチョビ・にんにく・マスタード・レモン・オリーブオイル・パルメザンチーズの手作りドレッシングを合わせます。ドレッシングは泡立て器で手作業で乳化させます。\n\n下ごしらえ20分、オーブンとフライパンの加熱で25分です。4人分です。","category":"サラダ","difficulty":"簡単","course":"メインディッシュ","cuisine":"アメリカ料理","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["チキンシーザーサラダ","シーザーサラダ レシピ","シーザードレッシング 手作り","クルトン 手作り","シーザーサラダ 鶏むね肉","シーザーサラダ 作り方","チキンサラダ"],"ingredients":[{"name":"食パン","amount":"120","unit":"g","group":"クルトン用"},{"name":"オリーブオイル","amount":"2","unit":"大さじ","group":"クルトン用"},{"name":"塩・黒こしょう","amount":"1","unit":"ひとつまみ","group":"クルトン用"},{"name":"鶏むね肉","amount":"500","unit":"g","group":"鶏肉用"},{"name":"オリーブオイル","amount":"1","unit":"大さじ","group":"鶏肉用"},{"name":"塩","amount":"1/2","unit":"小さじ","group":"鶏肉用"},{"name":"黒こしょう","amount":"1/2","unit":"小さじ","group":"鶏肉用"},{"name":"卵黄","amount":"1","unit":"","group":"ドレッシング用"},{"name":"アンチョビフィレ","amount":"4","unit":"","group":"ドレッシング用"},{"name":"にんにく","amount":"1","unit":"","group":"ドレッシング用"},{"name":"ディジョンマスタード","amount":"1","unit":"小さじ","group":"ドレッシング用"},{"name":"レモン果汁","amount":"2","unit":"大さじ","group":"ドレッシング用"},{"name":"オリーブオイル","amount":"80","unit":"ml","group":"ドレッシング用"},{"name":"パルメザンチーズ（すりおろし）","amount":"30","unit":"g","group":"ドレッシング用"},{"name":"ロメインレタスの芯に近い部分","amount":"2","unit":"","group":"サラダ用"},{"name":"パルメザンチーズ（薄く削ったもの）","amount":"30","unit":"g","group":"サラダ用"}],"steps":[{"title":"材料を準備する","content":"ロメインレタス2株分、鶏むね肉500g、食パン120g、パルメザンチーズ60g、卵黄1個、アンチョビ4枚、にんにく1片、レモン1個、ディジョンマスタード、オリーブオイルを用意します。オーブンを180°Cに予熱します。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"チキンシーザーサラダ: 材料を準備する"},{"title":"パンを切って味をつける","content":"食パン120gを2cm角に切り、クッキングシートを敷いた天板にのせます。オリーブオイル大さじ2と塩・こしょうをひとつまみ加えて混ぜ、重ならないように広げます。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"チキンシーザーサラダ: パンを切って味をつける"},{"title":"クルトンを焼く","content":"180°Cで12〜15分、途中で一度混ぜながら、黄金色でカリカリになるまで焼きます。天板の上で冷まします。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"チキンシーザーサラダ: クルトンを焼く"},{"title":"鶏肉を焼く","content":"鶏むね肉2枚を厚さ約2cmに平らにのばし、塩小さじ½とこしょう小さじ½をふります。フライパンに油大さじ1を中強火で熱し、片面5〜6分ずつ、中心が74°Cになるまで焼きます。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"チキンシーザーサラダ: 鶏肉を焼く"},{"title":"休ませて切る","content":"鶏肉をまな板に移して5分休ませ、肉汁を落ち着かせてから、斜めに厚さ1cmに切ります。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"チキンシーザーサラダ: 休ませて切る"},{"title":"ドレッシングを作る","content":"ボウルに卵黄1個、みじん切りにしたアンチョビ4枚、すりおろしたにんにく1片、マスタード小さじ1、レモン果汁大さじ2を入れて混ぜます。オリーブオイル80mlを細く垂らしながら、休まず混ぜてとろみをつけます。パルメザンチーズ30gとこしょうを好みで加えます。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"チキンシーザーサラダ: ドレッシングを作る"},{"title":"レタスをあえる","content":"ロメインレタス2株分を洗って水気をよく切り、4〜5cmにちぎります。ドレッシングの4分の3を加え、全体にからめます。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"チキンシーザーサラダ: レタスをあえる"},{"title":"盛りつける","content":"レタスを4枚の皿に分け、鶏肉とクルトンをのせ、削ったパルメザンチーズ30gと残りのドレッシングをかけます。レモンを添えて、すぐに食べます。","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"チキンシーザーサラダ: 盛りつける"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"チキンシーザーサラダ"}],"notes":"レタスの水気をよく切ります。水っぽいとドレッシングが流れてしまいます。葉とクルトンのカリカリ感を保つために、食べる直前にあえてください。ドレッシングに生の卵黄を使うため、子ども、妊娠中の方、高齢の方には低温殺菌卵を使ってください。卵、魚（アンチョビ）、乳、小麦を含みます。ドレッシングは密閉容器で冷蔵庫に2日、クルトンは密閉容器で常温に3日保存できます。鶏肉は前もって作り、温かくても冷たくても食べられます。","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1人分（皿1枚、約280g）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。ロメインレタス400g、生の鶏むね肉500g、食パン120g、パルメザンチーズ60g、卵黄17g、アンチョビ12g、にんにく4g、マスタード5g（おおよその値）、レモン果汁30g、塩3.5g、こしょう2g、オリーブオイル113.5g（レシピのすべての油で、一部がフライパンやボウルに残る分も含みます）を使用しています。","note":"1人分の目安です。実際に摂る油の量やパンの大きさで変わります。"},"seo":{"title":"チキンシーザーサラダの作り方｜手作りドレッシングとクルトン | Manual de Cocina","description":"ロメインレタス、焼いた鶏むね肉、オーブンで焼いたクルトン、アンチョビとレモンとパルメザンの手作りドレッシングのチキンシーザーサラダ。4人分。写真付き。","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"シーザードレッシングにアンチョビは入りますか？","a":"入ります。アンチョビは定番ドレッシングの味のもとです。細かくみじん切りにすると乳化したソースに溶け込み、魚のにおいは強く出ません。入れないと味がかなり変わります。"},{"q":"ドレッシングが分離しないようにするには？","a":"油を細く垂らしながら休まず混ぜ、材料は室温にもどしておきます。分離したら、別のボウルで卵黄を1個混ぜ、分離したドレッシングを少しずつ加えて混ぜます。"},{"q":"クルトンは前もって作れますか？","a":"作れます。密閉容器で常温に3日保存できます。しんなりしたら、オーブンで5分温め直します。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"4281a3a4-33e0-5868-85de-f82a22e9e9a3","recipe_group_id":"c14411e1-bbcd-4c1e-8635-126e71505ab1","language":"pt","slug":"salada-caesar-com-frango","public_path":"/pt/salada-caesar-com-frango","source_url":null,"title":"Salada Caesar com frango","excerpt":"Salada Caesar com frango: alface-romana, peito de frango selado, croutons dourados no forno e molho caseiro de anchova, limão e parmesão. Rende 4 porções.","summary":"A salada Caesar com frango combina alface-romana crocante com peito de frango selado, croutons dourados no forno e um molho caseiro de gema, anchova, alho, mostarda, limão, azeite e parmesão, emulsionado à mão com um fouet.\n\nLeva 20 minutos de preparo e 25 de cozimento entre o forno e a frigideira. Rende 4 porções.","category":"Saladas","difficulty":"Fácil","course":"Prato principal","cuisine":"Americana","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["salada caesar com frango","receita de salada caesar","molho caesar caseiro","croutons caseiros","salada caesar com peito de frango","como fazer salada caesar","salada de frango"],"ingredients":[{"name":"pão de forma","amount":"120","unit":"g","group":"Para os croutons"},{"name":"azeite","amount":"2","unit":"colher de sopa","group":"Para os croutons"},{"name":"sal e pimenta-do-reino","amount":"1","unit":"pitada","group":"Para os croutons"},{"name":"peitos de frango","amount":"500","unit":"g","group":"Para o frango"},{"name":"azeite","amount":"1","unit":"colher de sopa","group":"Para o frango"},{"name":"sal","amount":"1/2","unit":"colher de chá","group":"Para o frango"},{"name":"pimenta-do-reino","amount":"1/2","unit":"colher de chá","group":"Para o frango"},{"name":"gema de ovo","amount":"1","unit":"","group":"Para o molho"},{"name":"filés de anchova","amount":"4","unit":"","group":"Para o molho"},{"name":"alho","amount":"1","unit":"","group":"Para o molho"},{"name":"mostarda Dijon","amount":"1","unit":"colher de chá","group":"Para o molho"},{"name":"suco de limão","amount":"2","unit":"colher de sopa","group":"Para o molho"},{"name":"azeite","amount":"80","unit":"ml","group":"Para o molho"},{"name":"queijo parmesão ralado","amount":"30","unit":"g","group":"Para o molho"},{"name":"corações de alface-romana","amount":"2","unit":"","group":"Para a salada"},{"name":"queijo parmesão em lascas","amount":"30","unit":"g","group":"Para a salada"}],"steps":[{"title":"Separe os ingredientes","content":"Tenha à mão 2 corações de alface-romana, 500 g de peito de frango, 120 g de pão de forma, 60 g de parmesão, 1 gema, 4 filés de anchova, 1 dente de alho, 1 limão, mostarda Dijon e azeite. Preaqueça o forno a 180 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-01.webp","image_alt":"Salada Caesar com frango: Separe os ingredientes"},{"title":"Corte e tempere o pão","content":"Corte 120 g de pão de forma em cubos de 2 cm e coloque em uma assadeira forrada com papel-manteiga. Misture com 2 colheres de sopa de azeite e uma pitada de sal e pimenta e espalhe em uma só camada.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-02.webp","image_alt":"Salada Caesar com frango: Corte e tempere o pão"},{"title":"Asse os croutons","content":"Asse a 180 °C por 12 a 15 minutos, mexendo na metade, até ficarem dourados e crocantes. Deixe esfriar na assadeira.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-03.webp","image_alt":"Salada Caesar com frango: Asse os croutons"},{"title":"Sele o frango","content":"Achate 2 peitos de frango até cerca de 2 cm de espessura e tempere com ½ colher de chá de sal e ½ colher de chá de pimenta. Aqueça 1 colher de sopa de azeite em uma frigideira em fogo médio-alto e cozinhe os peitos de 5 a 6 minutos de cada lado, até o centro chegar a 74 °C.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-04.webp","image_alt":"Salada Caesar com frango: Sele o frango"},{"title":"Deixe descansar e corte o frango","content":"Passe o frango para uma tábua, deixe descansar por 5 minutos para não soltar os sucos e corte em fatias de 1 cm, na diagonal.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-05.webp","image_alt":"Salada Caesar com frango: Deixe descansar e corte o frango"},{"title":"Bata o molho","content":"Em uma tigela, bata 1 gema, 4 filés de anchova picados bem miúdos, 1 dente de alho ralado, 1 colher de chá de mostarda e 2 colheres de sopa de suco de limão. Junte 80 ml de azeite em fio fino, sem parar de bater, até engrossar. Incorpore 30 g de parmesão ralado e pimenta a gosto.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-06.webp","image_alt":"Salada Caesar com frango: Bata o molho"},{"title":"Misture a alface","content":"Lave e seque muito bem os 2 corações de alface-romana, rasgue em pedaços de 4 a 5 cm e misture com três quartos do molho até cobrir todas as folhas.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-07.webp","image_alt":"Salada Caesar com frango: Misture a alface"},{"title":"Monte e sirva","content":"Divida a alface em 4 pratos, coloque por cima o frango e os croutons, acrescente 30 g de parmesão em lascas e o molho restante. Sirva na hora, com limão ao lado.","image_url":"/recetas/ensalada-cesar-con-pollo/paso-08.webp","image_alt":"Salada Caesar com frango: Monte e sirva"}],"image_url":"/recetas/ensalada-cesar-con-pollo/portada.webp","gallery":[{"url":"/recetas/ensalada-cesar-con-pollo/portada.webp","alt":"Salada Caesar com frango"}],"notes":"Seque bem a alface: se estiver molhada, o molho escorre e a salada fica aguada. Tempere só na hora de servir para que as folhas e os croutons continuem crocantes. O molho leva gema crua; para crianças, grávidas ou idosos, use ovo pasteurizado. Contém ovo, peixe (anchova), leite e glúten. O molho dura 2 dias na geladeira em um pote fechado; os croutons, 3 dias em um recipiente hermético em temperatura ambiente. O frango pode ser preparado antes e servido morno ou frio.","nutrition":{"calories":582,"protein_g":39.1,"carbs_g":20,"fat_g":38.3,"sodium_mg":907,"serving_size":"1 porção (um prato, cerca de 280 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções: 400 g de alface-romana, 500 g de peito de frango cru, 120 g de pão de forma, 60 g de parmesão, 17 g de gema, 12 g de anchova, 4 g de alho, 5 g de mostarda (valores aproximados), 30 g de suco de limão, 3,5 g de sal, 2 g de pimenta e 113,5 g de azeite, que é todo o azeite da receita, mesmo que parte fique na frigideira ou na tigela.","note":"Estimativa por porção. O azeite realmente consumido e o tamanho do pão variam."},"seo":{"title":"Salada Caesar com frango: molho e croutons caseiros | Manual de Cocina","description":"Salada Caesar com frango: alface-romana, peito de frango selado, croutons no forno e molho caseiro de anchova, limão e parmesão. Rende 4 porções. Passo a passo com fotos.","image_variants":["/recetas/ensalada-cesar-con-pollo/portada-1x1.webp","/recetas/ensalada-cesar-con-pollo/portada-4x3.webp","/recetas/ensalada-cesar-con-pollo/portada-16x9.webp"],"faq":[{"q":"O molho Caesar leva anchova?","a":"Leva, a anchova é a base do sabor do molho clássico. Picada bem miúda, ela se dissolve na emulsão e não deixa gosto forte de peixe. Sem anchova, o molho muda bastante."},{"q":"Como evito que o molho talhe?","a":"Junte o azeite em fio bem fino enquanto bate sem parar e comece com todos os ingredientes em temperatura ambiente. Se talhar, bata outra gema em uma tigela limpa e vá juntando o molho talhado aos poucos."},{"q":"Posso fazer os croutons com antecedência?","a":"Pode. Duram 3 dias em um recipiente hermético em temperatura ambiente. Se amolecerem, volte ao forno por 5 minutos."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/ensalada-cesar') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
